CREATE VIEW "work_open_tasks" AS SELECT t."due_on" AS "due_on", t."flag" AS "flag", t."id" AS "id", t."important" AS "important", t."owner" AS "owner", t.planned_on AS "planned", t."project" AS "project", t."status" AS "status", t."title" AS "title", t."urgent" AS "urgent", t."workspace" AS "workspace" FROM work_tasks t WHERE t.status NOT IN ('done','canceled','replaced') AND t.parent IS NULL;

CREATE VIEW "work_this_week" AS SELECT t."due_on" AS "due_on", t."id" AS "id", t.planned_on AS "planned", t."project" AS "project", t."status" AS "status", t."title" AS "title", t."workspace" AS "workspace" FROM work_tasks t WHERE t.status NOT IN ('done','canceled','replaced') AND t.parent IS NULL AND (t.planned_on<=date('now','+7 days') OR t.due_on<=date('now','+7 days'));

CREATE VIEW "work_eisenhower" AS SELECT t."important" AS "important", CASE WHEN t.important=1 AND t.urgent=1 THEN 1 WHEN t.important=1 THEN 2 WHEN t.urgent=1 THEN 3 ELSE 4 END AS "quadrant", t.id AS "task", t.workspace AS "task_workspace", t."urgent" AS "urgent", t."workspace" AS "workspace" FROM work_tasks t WHERE t.status NOT IN ('done','canceled','replaced') AND t.parent IS NULL;

CREATE VIEW "work_in_review" AS SELECT t."due_on" AS "due_on", (SELECT a.path FROM work_attachments a WHERE a.subject_type='task' AND a.subject_id=t.id AND a.workspace=t.workspace ORDER BY a.seq DESC LIMIT 1) AS "evidence_path", t."id" AS "id", t."project" AS "project", t."status" AS "status", t."title" AS "title", t."workspace" AS "workspace" FROM work_tasks t WHERE t.status='in-review';

CREATE VIEW "work_next_step" AS SELECT t."id" AS "id", t."parent" AS "parent", t."sort_order" AS "sort_order", t."status" AS "status", t."title" AS "title", t."workspace" AS "workspace" FROM work_tasks t WHERE t.parent IS NOT NULL AND t.status IN ('todo','in-progress') AND t.id=(SELECT x.id FROM work_tasks x WHERE x.parent=t.parent AND x.status IN ('todo','in-progress') ORDER BY x.sort_order,x.id LIMIT 1);

CREATE VIEW "work_latest_run_per_task" AS SELECT r.id AS "run", r."started_at" AS "started_at", r."status" AS "status", r.subject_id AS "task" FROM work_runs r WHERE r.subject_type='task' AND NOT EXISTS(SELECT 1 FROM work_runs n WHERE n.subject_type='task' AND n.subject_id=r.subject_id AND n.workspace=r.workspace AND (n.started_at>r.started_at OR (n.started_at IS r.started_at AND n.id>r.id)));

CREATE VIEW "work_runs_to_place" AS SELECT r.id AS "run", t.id AS "standing_task", r."started_at" AS "started_at", r."status" AS "status" FROM work_runs r JOIN work_tasks t ON t.id=r.subject_id AND t.workspace=r.workspace WHERE r.subject_type='task' AND t.idempotency_key='session-holding-task';

CREATE VIEW "work_needs_me" AS SELECT CASE WHEN lower(t.owner)='@person@' THEN 'owner' WHEN t.reviewer='@person@' THEN 'reviewer' ELSE 'dependency' END AS "reason", t."status" AS "status", t.id AS "subject_id", 'task' AS "subject_type", t."title" AS "title", t."workspace" AS "workspace" FROM work_tasks t WHERE t.status NOT IN ('done','canceled','replaced') AND (lower(t.owner)='@person@' OR (t.status='in-review' AND t.reviewer='@person@') OR (t.status='blocked' AND EXISTS(SELECT 1 FROM work_links l JOIN work_tasks b ON b.id=l.subject_id WHERE l.target_id=t.id AND l.subject_type='task' AND l.target_type='task' AND l.relation='blocks' AND lower(b.owner)='@person@' AND b.status NOT IN ('done','canceled','replaced')))) UNION ALL SELECT 'proposal',p.status,p.id,'proposal',p.why,p.workspace FROM base_proposals p WHERE p.status='open' AND NOT EXISTS(SELECT 1 FROM base_approvals a WHERE a.subject_type='proposal' AND a.subject_id=p.id AND a.workspace=p.workspace AND a.action='approved' AND a.authorization_valid=1 AND a.approved_sha256=p.content_hash) UNION ALL SELECT 'draft',d.status,d.id,'draft',d.text,d.workspace FROM people_drafts d WHERE d.status='draft' AND NOT EXISTS(SELECT 1 FROM base_approvals a WHERE a.subject_type='draft' AND a.subject_id=d.id AND a.workspace=d.workspace AND a.action='approved' AND a.authorization_valid=1 AND a.version=d.version AND a.approved_sha256=d.content_hash);

CREATE VIEW "work_open_promises" AS SELECT (SELECT group_concat(l.target_id) FROM work_links l WHERE l.subject_id=t.id AND l.subject_type='task' AND l.relation='about') AS "about", t."due_on" AS "due_on", t."owner" AS "owner", t."sort_order" AS "sort_order", (SELECT group_concat(l.path) FROM work_links l WHERE l.subject_id=t.id AND l.subject_type='task' AND l.relation='source') AS "source", t.id AS "task" FROM work_tasks t WHERE t.status NOT IN ('done','canceled','replaced') AND EXISTS(SELECT 1 FROM work_links l JOIN base_values v ON v.id=l.target_id WHERE l.subject_id=t.id AND l.subject_type='task' AND l.relation='tagged' AND l.target_type='value' AND v.value='promise');

CREATE VIEW "work_program_plan" AS SELECT (SELECT count(*) FROM work_tasks z WHERE z.project=p.id AND z.parent IS NULL AND z.status='backlog') AS "backlog_tasks", t."claimed_by" AS "claimed_by", (SELECT count(*) FROM work_tasks z WHERE z.project=p.id AND z.parent IS NULL AND z.status='done') AS "done_tasks", (SELECT count(*) FROM work_tasks z WHERE z.project=p.id AND z.parent IS NULL AND z.status<>'canceled') AS "live_tasks", p.owner AS "owner", CASE WHEN ((SELECT count(*) FROM work_tasks z WHERE z.project=p.id AND z.parent IS NULL AND z.status<>'canceled')-(SELECT count(*) FROM work_tasks z WHERE z.project=p.id AND z.parent IS NULL AND z.status='backlog'))=0 THEN 0 ELSE 100.0*(SELECT count(*) FROM work_tasks z WHERE z.project=p.id AND z.parent IS NULL AND z.status='done')/((SELECT count(*) FROM work_tasks z WHERE z.project=p.id AND z.parent IS NULL AND z.status<>'canceled')-(SELECT count(*) FROM work_tasks z WHERE z.project=p.id AND z.parent IS NULL AND z.status='backlog')) END AS "percent_done", g.name AS "program", t."status" AS "status", p.title AS "stream", p.id AS "stream_id", p.workspace AS "stream_id_workspace", p.sort_order AS "stream_sort_order", p.status AS "stream_status", t.title AS "task", t.id AS "task_id", t.workspace AS "task_id_workspace", t.sort_order AS "task_sort_order", h.name AS "theme", h.sort_order AS "theme_sort_order", p.workspace AS "workspace" FROM work_projects p JOIN work_programs g ON g.id=p.program LEFT JOIN work_themes h ON h.id=p.theme LEFT JOIN work_tasks t ON t.project=p.id AND t.parent IS NULL WHERE p.status<>'replaced';

CREATE VIEW "work_ready_to_merge" AS SELECT EXISTS(SELECT 1 FROM work_changes c WHERE c.subject_type='task' AND c.subject_id=t.id AND c.workspace=t.workspace AND c.action IN ('verified','accepted') AND c.subject_version=CAST(t.version AS TEXT) AND c.actor=CASE WHEN t.reviewer='@person@' THEN '@person@' ELSE t.reviewed_by END) AS "check_passed", l.path AS "pull_request", l.system AS "pull_request_source_database", l.target_type AS "pull_request_source_table", t."status" AS "status", t.id AS "task", t.workspace AS "task_workspace", t."workspace" AS "workspace" FROM work_tasks t JOIN work_links l ON l.subject_type='task' AND l.subject_id=t.id AND l.workspace=t.workspace AND l.relation='produced' AND l.system='github' WHERE t.status='in-review' AND EXISTS(SELECT 1 FROM work_changes c WHERE c.subject_type='task' AND c.subject_id=t.id AND c.workspace=t.workspace AND c.action IN ('verified','accepted') AND c.subject_version=CAST(t.version AS TEXT) AND c.actor=CASE WHEN t.reviewer='@person@' THEN '@person@' ELSE t.reviewed_by END) AND NOT EXISTS(SELECT 1 FROM work_changes c WHERE c.subject_id=t.id AND c.subject_type='task' AND c.workspace=t.workspace AND c.action='merged' AND EXISTS(SELECT 1 FROM json_each(c.refs) r WHERE r.value=l.path));

CREATE VIEW "base_dictionary" AS SELECT o."collection" AS "collection", f."description" AS "description", f."field" AS "field", f."field_type" AS "field_type", o."lens" AS "lens", f."link_target" AS "link_target", m.name AS "module", o.name AS "object_type", f.sort_order AS "ordinal", f."pick_values" AS "pick_values", f."required" AS "required", o."supertype" AS "supertype" FROM base_object_types o JOIN base_modules m ON m.id=o.module LEFT JOIN base_fields f ON f.object_type=o.id;

CREATE VIEW "base_open_decisions" AS SELECT d."decided_on" AS "decided_on", d."id" AS "id", d."name" AS "name", d."status" AS "status", coalesce(p.workspace,f.workspace) AS "workspace" FROM base_decisions d LEFT JOIN work_projects p ON p.id=d.project LEFT JOIN work_functions f ON f.id=d.function WHERE d.status IN ('open','soft');

CREATE VIEW base_timeline AS SELECT "action" AS "action","actor" AS "actor","occurred_at" AS "occurred_at","refs" AS "refs","seq" AS "seq","session" AS "session","subject_id" AS "subject_id","subject_type" AS "subject_type","summary" AS "summary",'work_changes' AS "table","workspace" AS "workspace" FROM work_changes UNION ALL SELECT "action" AS "action","actor" AS "actor","occurred_at" AS "occurred_at","refs" AS "refs","seq" AS "seq","session" AS "session","subject_id" AS "subject_id","subject_type" AS "subject_type","summary" AS "summary",'work_comments' AS "table","workspace" AS "workspace" FROM work_comments UNION ALL SELECT "action" AS "action","actor" AS "actor","occurred_at" AS "occurred_at","refs" AS "refs","seq" AS "seq","session" AS "session","subject_id" AS "subject_id","subject_type" AS "subject_type","summary" AS "summary",'work_attachments' AS "table","workspace" AS "workspace" FROM work_attachments UNION ALL SELECT "action" AS "action","actor" AS "actor","occurred_at" AS "occurred_at","refs" AS "refs","seq" AS "seq","session" AS "session","subject_id" AS "subject_id","subject_type" AS "subject_type","summary" AS "summary",'base_approvals' AS "table","workspace" AS "workspace" FROM base_approvals UNION ALL SELECT "action" AS "action","actor" AS "actor","occurred_at" AS "occurred_at","refs" AS "refs","seq" AS "seq","session" AS "session","subject_id" AS "subject_id","subject_type" AS "subject_type","summary" AS "summary",'base_receipts' AS "table","workspace" AS "workspace" FROM base_receipts ORDER BY seq;

CREATE VIEW "amazon_families" AS SELECT count(DISTINCT l.asin) AS "child_count", l."marketplace" AS "marketplace", l."parent_asin" AS "parent_asin" FROM amazon_listings l WHERE l.parent_asin IS NOT NULL GROUP BY l.parent_asin,l.marketplace;

CREATE VIEW "amazon_open_compliance_cases" AS SELECT c."account" AS "account", a.workspace AS "account_workspace", c."doc_status" AS "doc_status", c."due_on" AS "due_on", c."id" AS "id", l."marketplace" AS "marketplace", c."owner" AS "owner", c."requirement" AS "requirement", l."seller_sku" AS "seller_sku", c."status" AS "status", c."updated_at" AS "updated_at", c."workspace" AS "workspace" FROM amazon_compliance_cases c LEFT JOIN amazon_listings l ON l.id=c.listing LEFT JOIN commerce_accounts a ON a.id=c.account WHERE c.status NOT IN ('closed','resolved');

CREATE VIEW "amazon_suppressed_listings" AS SELECT l."account" AS "account", l."asin" AS "asin", l."fetched_at" AS "fetched_at", l."marketplace" AS "marketplace", l."seller_sku" AS "seller_sku", l."source_status" AS "source_status", l.status_reason AS "suppression_reason", l."title" AS "title" FROM amazon_listings l WHERE l.is_suppressed=1;

CREATE VIEW "amazon_market_availability" AS SELECT k.account AS "account", max(l.fetched_at) AS "fetched_at", max(l.is_buyable) AS "is_buyable", k.marketplace AS "marketplace", k.sku_ref AS "sku_ref", CASE WHEN max(l.is_buyable)=1 THEN 'buyable' WHEN s.status='retired' THEN 'closed' WHEN EXISTS(SELECT 1 FROM amazon_compliance_cases c JOIN amazon_listings z ON z.id=c.listing WHERE c.account=k.account AND z.sku_ref=k.sku_ref AND z.marketplace=k.marketplace AND c.status NOT IN ('closed','resolved')) THEN 'compliance' WHEN lower(u.result) IN ('failed','error','rejected') OR s.status='blocked' OR max(l.is_suppressed)=1 OR max(CASE WHEN l.source_status='missing-required' THEN 1 ELSE 0 END)=1 THEN 'to-fix' WHEN s.status='submitted' THEN 'waiting' WHEN count(l.id)=0 THEN 'not-started' WHEN max(l.quantity)=0 OR max(l.is_own_offer)=0 THEN 'created' ELSE 'waiting' END AS "stage", CASE WHEN max(l.is_buyable)=1 THEN CASE WHEN max(CASE WHEN l.is_buyable=1 AND lower(l.fulfillment)='fba' THEN 1 ELSE 0 END)=1 AND max(CASE WHEN l.is_buyable=1 AND lower(l.fulfillment)='fbm' THEN 1 ELSE 0 END)=1 THEN 'active-both' WHEN max(CASE WHEN l.is_buyable=1 AND lower(l.fulfillment)='fba' THEN 1 ELSE 0 END)=1 THEN 'active-fba' ELSE 'active-fbm' END WHEN s.status='retired' THEN 'closed' WHEN EXISTS(SELECT 1 FROM amazon_compliance_cases c JOIN amazon_listings z ON z.id=c.listing WHERE c.account=k.account AND z.sku_ref=k.sku_ref AND z.marketplace=k.marketplace AND c.status NOT IN ('closed','resolved') AND c.doc_status='submitted') THEN 'documents-submitted' WHEN EXISTS(SELECT 1 FROM amazon_compliance_cases c JOIN amazon_listings z ON z.id=c.listing WHERE c.account=k.account AND z.sku_ref=k.sku_ref AND z.marketplace=k.marketplace AND c.status NOT IN ('closed','resolved')) THEN 'blocked' WHEN lower(u.result) IN ('failed','error','rejected') OR s.status='blocked' THEN 'blocked' WHEN s.status='submitted' THEN CASE s.change_type WHEN 'offer' THEN 'offer-submitted' WHEN 'fba-switch' THEN 'fba-submitted' ELSE 'listing-submitted' END WHEN max(l.is_suppressed)=1 THEN 'suppressed' WHEN max(CASE WHEN l.source_status='missing-required' THEN 1 ELSE 0 END)=1 THEN 'missing-required' WHEN max(CASE WHEN l.source_status='no-channel' THEN 1 ELSE 0 END)=1 THEN 'no-channel' WHEN count(l.id)=0 THEN 'no-listing' WHEN max(l.is_own_offer)=0 THEN 'other-seller-only' WHEN max(l.quantity)=0 THEN 'no-offer' ELSE 'no-buyable-offers' END AS "status" FROM (SELECT account,marketplace,sku_ref FROM amazon_listing_changes UNION SELECT account,marketplace,sku_ref FROM amazon_listings WHERE sku_ref IS NOT NULL) k
 LEFT JOIN amazon_listing_changes s ON s.id=(SELECT x.id FROM amazon_listing_changes x WHERE x.account=k.account AND x.marketplace=k.marketplace AND x.sku_ref=k.sku_ref ORDER BY x.created_at DESC,x.id DESC LIMIT 1)
 LEFT JOIN amazon_listing_submissions u ON u.id=(SELECT x.id FROM amazon_listing_submissions x WHERE x.listing_change=s.id ORDER BY x.submitted_at DESC,x.id DESC LIMIT 1)
 LEFT JOIN amazon_listings l ON l.account=k.account AND l.marketplace=k.marketplace AND l.sku_ref=k.sku_ref GROUP BY k.sku_ref,k.account,k.marketplace;

CREATE VIEW "amazon_scope_buyable" AS SELECT count(DISTINCT l.asin) AS "buyable_asins", l."marketplace" AS "marketplace", (SELECT m.target FROM work_measures m WHERE m.workspace=l.workspace AND m.source='amazon_scope_buyable' ORDER BY m.id LIMIT 1) AS "target" FROM amazon_listings l WHERE l.is_buyable=1 AND l.marketplace IN ('US','CA') AND EXISTS(SELECT 1 FROM amazon_listing_changes s WHERE s.sku_ref=l.sku_ref AND s.account=l.account AND s.marketplace=l.marketplace AND s.status='draft') GROUP BY l.marketplace;

CREATE VIEW "commerce_low_stock" AS SELECT CASE WHEN a.source_system='amazon' THEN a.id END AS "amazon_account_id", CASE WHEN a.source_system='amazon' THEN a.workspace END AS "amazon_account_workspace", i."available" AS "available", a.id AS "commerce_account_id", a.source_system AS "commerce_account_source_system", i."fetched_at" AS "fetched_at", i."inbound" AS "inbound", i."location_id" AS "location_id", i."sku" AS "sku", a.source_account_id AS "source_account_id", a.source_system AS "source_system" FROM commerce_inventory_levels i JOIN commerce_accounts a ON a.id=i.account WHERE i.available<=0;

CREATE VIEW commerce_mirror_age AS SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM amazon_listings ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'amazon_listings' AS "table" FROM amazon_listings UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM commerce_customer_reviews ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'commerce_customer_reviews' AS "table" FROM commerce_customer_reviews UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM commerce_inventory_levels ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'commerce_inventory_levels' AS "table" FROM commerce_inventory_levels UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM commerce_line_items ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'commerce_line_items' AS "table" FROM commerce_line_items UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM commerce_orders ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'commerce_orders' AS "table" FROM commerce_orders UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM commerce_prices ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'commerce_prices' AS "table" FROM commerce_prices UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM commerce_products ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'commerce_products' AS "table" FROM commerce_products UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM commerce_sales ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'commerce_sales' AS "table" FROM commerce_sales UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM commerce_sales_reports ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'commerce_sales_reports' AS "table" FROM commerce_sales_reports UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM commerce_shipments ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'commerce_shipments' AS "table" FROM commerce_shipments UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM commerce_skus ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'commerce_skus' AS "table" FROM commerce_skus UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,NULL AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'people_conversations' AS "table" FROM people_conversations UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM people_messages ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'people_messages' AS "table" FROM people_messages UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM treasury_transactions ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'treasury_transactions' AS "table" FROM treasury_transactions UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM treasury_transfer_legs ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'treasury_transfer_legs' AS "table" FROM treasury_transfer_legs UNION ALL SELECT CAST(strftime('%s','now') AS INTEGER)-CAST(strftime('%s',max(fetched_at)) AS INTEGER) AS age_seconds,(SELECT status FROM work_runs WHERE id=(SELECT refresh_run FROM ugc_media_files ORDER BY fetched_at DESC LIMIT 1)) AS last_run_status,max(fetched_at) AS newest_fetched_at,count(*) AS row_count,'ugc_media_files' AS "table" FROM ugc_media_files;

CREATE VIEW "commerce_open_support_cases" AS SELECT c."id" AS "id", c."next_action" AS "next_action", c."next_action_due_on" AS "next_action_due_on", c."owner" AS "owner", c.platform AS "source", c."status" AS "status", c."subject" AS "subject", c."updated_at" AS "updated_at", c."workspace" AS "workspace" FROM commerce_support_cases c WHERE c.status NOT IN ('closed','resolved');

CREATE VIEW "commerce_restock_due" AS SELECT r."approved_quantity" AS "approved_quantity", CAST(julianday(date('now'))-julianday(r.due_on) AS INTEGER) AS "days_overdue", r.destination_location_id AS "destination_location_id", r."due_on" AS "due_on", r."id" AS "id", r."requested_quantity" AS "requested_quantity", r."sku" AS "sku", r."status" AS "status", r."workspace" AS "workspace" FROM commerce_restocks r WHERE r.status IN ('planned','approved','ordered','in-transit') AND r.due_on IS NOT NULL AND r.due_on<=date('now');

CREATE VIEW "commerce_restock_plan" AS SELECT (SELECT x.recommended_quantity FROM commerce_restock_recommendations x WHERE x.restock=r.id AND x.source='amazon' ORDER BY x.as_of DESC,x.id DESC LIMIT 1) AS "amazon_recommended", (SELECT x.recommended_quantity FROM commerce_restock_recommendations x WHERE x.restock=r.id AND x.source='amazon' ORDER BY x.as_of DESC,x.id DESC LIMIT 1)-(SELECT x.recommended_quantity FROM commerce_restock_recommendations x WHERE x.restock=r.id AND x.source='helium-10' ORDER BY x.as_of DESC,x.id DESC LIMIT 1) AS "delta", (SELECT x.recommended_quantity FROM commerce_restock_recommendations x WHERE x.restock=r.id AND x.source='helium-10' ORDER BY x.as_of DESC,x.id DESC LIMIT 1) AS "helium_10_recommended", r.id AS "restock", (SELECT sum(li.quantity) FROM commerce_shipments sh JOIN commerce_line_items li ON li."order"=sh."order" WHERE sh.id=r.shipment AND li.sku_ref=r.sku_ref) AS "sent", 100.0*(SELECT sum(li.quantity) FROM commerce_shipments sh JOIN commerce_line_items li ON li."order"=sh."order" WHERE sh.id=r.shipment AND li.sku_ref=r.sku_ref)/nullif(r.approved_quantity,0) AS "shipbob_percent", r.approved_quantity-(SELECT sum(li.quantity) FROM commerce_shipments sh JOIN commerce_line_items li ON li."order"=sh."order" WHERE sh.id=r.shipment AND li.sku_ref=r.sku_ref) AS "short", r."sku_ref" AS "sku_ref" FROM commerce_restocks r;

CREATE VIEW "people_contacts_due" AS SELECT c.id AS "contact", date((SELECT max(i.occurred_at) FROM people_interactions i WHERE i.contact=c.id), '+' || CASE c.tier WHEN 1 THEN 4 WHEN 2 THEN 14 WHEN 3 THEN 30 WHEN 4 THEN 90 END || ' days') AS "due_on", (SELECT max(i.occurred_at) FROM people_interactions i WHERE i.contact=c.id) AS "last_contact_at", c."name" AS "name", c."register" AS "register", c."tier" AS "tier" FROM people_contacts c WHERE (SELECT max(i.occurred_at) FROM people_interactions i WHERE i.contact=c.id) IS NULL OR date((SELECT max(i.occurred_at) FROM people_interactions i WHERE i.contact=c.id), '+' || CASE c.tier WHEN 1 THEN 4 WHEN 2 THEN 14 WHEN 3 THEN 30 WHEN 4 THEN 90 END || ' days')<=date('now');

CREATE VIEW "people_contacts_without_handles" AS SELECT c."id" AS "id", c."name" AS "name", c."note_path" AS "note_path" FROM people_contacts c WHERE NOT EXISTS(SELECT 1 FROM people_handles h WHERE h.contact=c.id);

CREATE VIEW "people_message_workspaces" AS SELECT m."account" AS "account", m."channel" AS "channel", m."source_message_id" AS "source_message_id", CASE WHEN json_array_length(coalesce(m.workspace_tags,c.workspace_tags,'[]'))=0 THEN '["@personal_workspace@"]' ELSE coalesce(m.workspace_tags,c.workspace_tags,'[]') END AS "workspace_tags" FROM people_messages m JOIN people_conversations c ON c.id=m.conversation;

CREATE VIEW "people_messages_sent_by_person" AS SELECT m."conversation" AS "conversation", m.id AS "message", m."sent_at" AS "sent_at", m."source_system" AS "source_system" FROM people_messages m WHERE m.direction IN ('out','outbound','sent') AND NOT EXISTS(SELECT 1 FROM people_drafts d WHERE d.sent_message=m.id);

CREATE VIEW "people_conversations_in_hand" AS SELECT (SELECT x.actor FROM work_changes x WHERE x.subject_type='draft' AND x.subject_id=d.id AND x.action='created' ORDER BY x.seq LIMIT 1) AS "agent", d."conversation" AS "conversation", d."created_at" AS "created_at", d.id AS "draft", (SELECT max(z.at) FROM (SELECT coalesce(d.updated_at,d.created_at) AS at UNION ALL SELECT x.occurred_at FROM work_changes x JOIN people_draft_facts f ON f.id=x.subject_id WHERE x.subject_type='draft-fact' AND f.draft=d.id) z) AS "last_change_at", CASE WHEN (SELECT max(z.at) FROM (SELECT coalesce(d.updated_at,d.created_at) AS at UNION ALL SELECT x.occurred_at FROM work_changes x JOIN people_draft_facts f ON f.id=x.subject_id WHERE x.subject_type='draft-fact' AND f.draft=d.id) z) IS NULL THEN NULL WHEN julianday('now')-julianday((SELECT max(z.at) FROM (SELECT coalesce(d.updated_at,d.created_at) AS at UNION ALL SELECT x.occurred_at FROM work_changes x JOIN people_draft_facts f ON f.id=x.subject_id WHERE x.subject_type='draft-fact' AND f.draft=d.id) z))>=1 THEN 1 ELSE 0 END AS "stale", d."status" AS "status", d."workspace" AS "workspace" FROM people_drafts d WHERE d.status NOT IN ('sent','skipped','replaced');

CREATE VIEW "people_open_conversations" AS SELECT c."account" AS "account", c."channel" AS "channel", c."fetched_at" AS "fetched_at", c."function" AS "function", f.workspace AS "function_workspace", c."id" AS "id", (SELECT max(m.sent_at) FROM people_messages m WHERE m.conversation=c.id) AS "last_message_at", (SELECT count(*) FROM people_participants p WHERE p.conversation=c.id) AS "participant_count", c."status" AS "status", c."title" AS "title", CASE WHEN json_array_length(c.workspace_tags)=0 THEN '@personal_workspace@' ELSE json_extract(c.workspace_tags,'$[0]') END AS "workspace" FROM people_conversations c LEFT JOIN work_functions f ON f.id=c.function WHERE c.status='open';

CREATE VIEW "people_opportunities_by_stage" AS SELECT o."contact" AS "contact", c.name AS "contact_name", o."currency" AS "currency", CAST(julianday(date('now'))-julianday(date(coalesce((SELECT max(x.occurred_at) FROM work_changes x WHERE x.subject_id=o.id AND x.subject_type='opportunity' AND x.workspace=o.workspace AND x.field='stage'),o.created_at))) AS INTEGER) AS "days_in_stage", (SELECT t.title FROM work_tasks t JOIN work_links a ON a.subject_type='task' AND a.subject_id IN (t.id,t.parent) AND a.target_type='opportunity' AND a.target_id=o.id AND a.workspace=o.workspace AND a.relation='about'
 JOIN work_links tag ON tag.subject_type='task' AND tag.subject_id=t.id AND tag.relation='tagged' AND tag.target_type='value'
 JOIN base_values v ON v.id=tag.target_id AND v."set"='next-action'
 WHERE t.parent IS NOT NULL AND t.status NOT IN ('done','canceled','replaced') ORDER BY t.sort_order,t.id LIMIT 1) AS "next_step", o.id AS "opportunity", o.workspace AS "opportunity_workspace", o."organization" AS "organization", o."outcome" AS "outcome", o."owner" AS "owner", s.pipeline AS "pipeline", s."sort_order" AS "sort_order", s.id AS "stage", s.pipeline AS "stage_pipeline", s."target_days" AS "target_days", o."title" AS "title", o."value_minor" AS "value_minor", coalesce((SELECT t.owner FROM work_tasks t JOIN work_links a ON a.subject_type='task' AND a.subject_id IN (t.id,t.parent) AND a.target_type='opportunity' AND a.target_id=o.id AND a.workspace=o.workspace AND a.relation='about'
 JOIN work_links tag ON tag.subject_type='task' AND tag.subject_id=t.id AND tag.relation='tagged' AND tag.target_type='value'
 JOIN base_values v ON v.id=tag.target_id AND v."set"='next-action'
 WHERE t.parent IS NOT NULL AND t.status NOT IN ('done','canceled','replaced') ORDER BY t.sort_order,t.id LIMIT 1),CASE (SELECT m.direction FROM people_interactions i JOIN people_messages m ON m.id=i.source_message WHERE i.opportunity=o.id ORDER BY m.sent_at DESC,m.id DESC LIMIT 1) WHEN 'inbound' THEN '@person@' WHEN 'outbound' THEN c.name END) AS "whose_move", coalesce((SELECT v.value FROM work_tasks t JOIN work_links a ON a.subject_type='task' AND a.subject_id IN (t.id,t.parent) AND a.target_type='opportunity' AND a.target_id=o.id AND a.workspace=o.workspace AND a.relation='about'
 JOIN work_links tag ON tag.subject_type='task' AND tag.subject_id=t.id AND tag.relation='tagged' AND tag.target_type='value'
 JOIN base_values v ON v.id=tag.target_id AND v."set"='next-action'
 WHERE t.parent IS NOT NULL AND t.status NOT IN ('done','canceled','replaced') ORDER BY t.sort_order,t.id LIMIT 1),CASE (SELECT m.direction FROM people_interactions i JOIN people_messages m ON m.id=i.source_message WHERE i.opportunity=o.id ORDER BY m.sent_at DESC,m.id DESC LIMIT 1) WHEN 'inbound' THEN 'reply' WHEN 'outbound' THEN 'reply' END) AS "whose_move_reason" FROM people_pipeline_stages s LEFT JOIN people_opportunities o ON o.stage=s.id AND o.pipeline=s.pipeline AND o.outcome='open' LEFT JOIN people_contacts c ON c.id=o.contact;

CREATE VIEW "treasury_money_owed" AS SELECT t."amount_minor" AS "amount_minor", t."currency" AS "currency", CAST(julianday(date('now'))-julianday(t.due_on) AS INTEGER) AS "days_overdue", t."due_on" AS "due_on", t."id" AS "id", t."payee" AS "payee", t."status" AS "status" FROM treasury_scheduled_transactions t WHERE t.direction='in' AND t.status IN ('expected','due');

CREATE VIEW "treasury_payments" AS SELECT t.amount_milliunits/10.0 AS "amount_minor", t."category_id" AS "category_id", t."cleared" AS "cleared", t."currency" AS "currency", t."date" AS "date", t."payee_name" AS "payee_name", t."source_id" AS "source_id" FROM treasury_transactions t WHERE t.deleted=0;

CREATE VIEW "ugc_missing_content" AS SELECT (SELECT count(*) FROM ugc_deliverable_content dc JOIN design_content c ON c.id=dc.content WHERE dc.deliverable=d.id AND c.status IN ('approved','published')) AS "accepted_quantity", (SELECT count(DISTINCT m.file_hash) FROM ugc_media_files m WHERE m.deliverable=d.id AND m.identity_status='verified' AND m.availability='available' AND (m.expires_at IS NULL OR julianday(m.expires_at)>julianday('now'))) AS "available_file_count", d.id AS "deliverable", d.workspace AS "deliverable_workspace", (SELECT count(*) FROM ugc_deliverable_content dc WHERE dc.deliverable=d.id) AS "delivered_quantity", d."due_on" AS "due_on", d."format" AS "format", (SELECT count(DISTINCT m.file_hash) FROM ugc_media_files m WHERE m.deliverable=d.id AND m.identity_status='verified') AS "observed_file_count", (SELECT count(*) FROM ugc_file_requests f WHERE f.opportunity=d.opportunity AND f.status NOT IN ('closed','canceled','received')) AS "open_file_request_count", d."opportunity" AS "opportunity", o.workspace AS "opportunity_workspace", d."platform" AS "platform", d."quantity" AS "quantity", d."status" AS "status" FROM ugc_deliverables d JOIN people_opportunities o ON o.id=d.opportunity WHERE d.status<>'waived' AND ((SELECT count(*) FROM ugc_deliverable_content dc WHERE dc.deliverable=d.id)<d.quantity OR d.quantity IS NULL);

CREATE VIEW "ugc_payments_owed" AS SELECT o."agreed_amount_minor" AS "agreed_amount_minor", (SELECT max(b.seq) FROM base_approvals b WHERE b.subject_type='scheduled-transaction' AND b.subject_id=s.id AND b.workspace=s.workspace AND b.action='approved') AS "approval_seq", CASE WHEN (CASE WHEN tx.deleted=0 AND tx.currency=s.currency AND tx.amount_milliunits<0 THEN -tx.amount_milliunits/10.0 END) IS NULL THEN 1 ELSE 0 END AS "ask_person", o."contact" AS "contact", s.currency AS "currency", o.id AS "opportunity", o.workspace AS "opportunity_workspace", s.amount_minor-(CASE WHEN tx.deleted=0 AND tx.currency=s.currency AND tx.amount_milliunits<0 THEN -tx.amount_milliunits/10.0 END) AS "owed_minor", CASE WHEN tx.deleted=0 AND tx.currency=s.currency AND tx.amount_milliunits<0 THEN -tx.amount_milliunits/10.0 END AS "paid_minor", a.seq AS "proof_attachment", s.id AS "scheduled_transaction", s.workspace AS "scheduled_transaction_workspace" FROM treasury_scheduled_transactions s JOIN people_opportunities o ON o.id=s.opportunity JOIN people_pipelines p ON p.id=o.pipeline LEFT JOIN treasury_transactions tx ON tx.id=s."transaction" LEFT JOIN work_attachments a ON a.subject_type='scheduled-transaction' AND a.subject_id=s.id AND a.workspace=s.workspace AND a.seq=(SELECT max(x.seq) FROM work_attachments x WHERE x.subject_type='scheduled-transaction' AND x.subject_id=s.id AND x.workspace=s.workspace) WHERE p.name='creators' AND s.direction='out' AND s.status NOT IN ('skipped','written-off','canceled');

CREATE VIEW "ugc_reply_queue" AS SELECT c."channel" AS "channel", c."id" AS "id", c."last_message_at" AS "last_message_at", c."participant_count" AS "participant_count", c."title" AS "title" FROM people_open_conversations c JOIN work_functions f ON f.id=c.function WHERE f.name='ugc';

CREATE VIEW "ugc_rights_expiring" AS SELECT r."content" AS "content", c.workspace AS "content_workspace", r."creator" AS "creator", CAST(julianday(r.valid_until)-julianday(date('now')) AS INTEGER) AS "days_remaining", r."id" AS "id", r."platform" AS "platform", CASE WHEN r.status<>'granted' THEN r.status WHEN r.valid_from IS NULL OR r.valid_until IS NULL OR r.platform IS NULL OR r.territory IS NULL THEN 'unknown_scope' WHEN r.valid_until<date('now') THEN 'expired' WHEN r.valid_until<=date('now','+30 days') THEN 'expiring' ELSE 'check_required' END AS "rights_status", r."status" AS "status", r."territory" AS "territory", r."usage" AS "usage", r."valid_until" AS "valid_until" FROM ugc_usage_rights r LEFT JOIN design_content c ON c.id=r.content WHERE r.status<>'granted' OR r.valid_from IS NULL OR r.valid_until IS NULL OR r.platform IS NULL OR r.territory IS NULL OR r.valid_until<=date('now','+30 days');
